-- Migration 0006: assistant prefs, reminder categories, reminders, AI usage (users 7 and 8)
create function t.as_service() returns void language plpgsql as $$ begin reset role; perform set_config('request.jwt.claim.sub', '', false); set role service_role; end $$;
insert into auth.users (id) values ('77777777-0000-0000-0000-000000000007'), ('88888888-0000-0000-0000-000000000008');
select t.as_user('88888888-0000-0000-0000-000000000008'); insert into public.tasks (title) values ('Eight task');
select t.su(); insert into t.ids select 'task8', id from public.tasks where title = 'Eight task';
select t.as_user('77777777-0000-0000-0000-000000000007'); insert into public.tasks (title) values ('Seven task');
select t.su(); insert into t.ids select 'task7', id from public.tasks where title = 'Seven task';
select t.as_user('77777777-0000-0000-0000-000000000007');
select t.ok('assistant name starts empty and AI opt-in starts OFF', (select assistant_name is null and ai_opt_in = false from public.preferences));
select t.ok('user can set own assistant name and opt in', t.affected($$update public.preferences set assistant_name = 'Nova', ai_opt_in = true$$) = 1);
select t.ok('accents, apostrophes and hyphens are allowed', t.affected($$update public.preferences set assistant_name = 'Zoë O''Neil-Smith'$$) = 1);
select t.fails('name over 30 characters rejected', $$update public.preferences set assistant_name = repeat('a', 31)$$);
select t.fails('empty name rejected (reset uses NULL)', $$update public.preferences set assistant_name = ''$$);
select t.fails('name with leading space rejected', $$update public.preferences set assistant_name = ' Nova'$$);
select t.fails('name with markup characters rejected', $$update public.preferences set assistant_name = '<b>Nova</b>'$$);
select t.ok('reset to default (NULL) works', t.affected($$update public.preferences set assistant_name = null$$) = 1);
select t.fails('unknown muted reminder category rejected', $$insert into public.reminder_settings (muted_categories) values ('{bogus}')$$);
insert into public.reminder_settings (muted_categories) values ('{task,habit}');
insert into public.reminders (title, kind, remind_at, tz, rrule) values ('Study maths', 'study', '2026-10-20 08:00+00', 'Europe/London', '{"freq":"daily"}');
select t.ok('owner can create and read a recurring reminder', (select count(*) from public.reminders) = 1 and (select status from public.reminders) = 'active');
select t.fails('empty title rejected', $$insert into public.reminders (title, remind_at) values ('', now())$$);
select t.fails('unknown kind rejected', $$insert into public.reminders (title, kind, remind_at) values ('x', 'spam', now())$$);
select t.fails('notes over 500 characters rejected', $$insert into public.reminders (title, notes, remind_at) values ('x', repeat('n', 501), now())$$);
select t.fails('invalid timezone rejected', $$insert into public.reminders (title, remind_at, tz) values ('x', now(), 'Mars/Base')$$);
select t.fails('unknown status rejected', $$insert into public.reminders (title, remind_at, status) values ('x', now(), 'weird')$$);
select t.fails('rrule must be an object', $$insert into public.reminders (title, remind_at, rrule) values ('x', now(), '[1]')$$);
select t.fails('cannot link a reminder to someone else''s task', $$insert into public.reminders (title, remind_at, task_id) select 'x', now(), v from t.ids where k = 'task8'$$);
select t.ok('can link a reminder to own task', t.affected($$insert into public.reminders (title, remind_at, task_id) select 'Do it', now(), v from t.ids where k = 'task7'$$) = 1);
select t.ok('snooze/dismiss fields can be updated by the owner', t.affected($$update public.reminders set snoozed_until = now() + interval '10 min', skip_until = now() where title = 'Study maths'$$) = 1);
select t.fails('cannot hand a reminder to another user', $$update public.reminders set user_id = '88888888-0000-0000-0000-000000000008'$$);
select t.as_user('88888888-0000-0000-0000-000000000008');
select t.ok('other user sees none of these reminders, settings or names', t.cnt('select 1 from public.reminders') + t.cnt('select 1 from public.reminder_settings') = 0 and (select assistant_name is null and ai_opt_in = false from public.preferences));
select t.ok('other user cannot edit or delete them', t.affected($$update public.reminders set title = 'pwned'$$) + t.affected($$delete from public.reminders$$) + t.affected($$update public.preferences set assistant_name = 'Hijack' where user_id = '77777777-0000-0000-0000-000000000007'$$) = 0);
select t.fails('other user cannot create a reminder in someone else''s name', $$insert into public.reminders (user_id, title, remind_at) values ('77777777-0000-0000-0000-000000000007', 'x', now())$$);
select t.as_user('77777777-0000-0000-0000-000000000007');
delete from public.tasks where title = 'Seven task';
select t.ok('deleting a task keeps the reminder but unlinks it', (select count(*) from public.reminders where title = 'Do it' and task_id is null) = 1);
select t.fails('clients cannot read the AI usage counter', 'select * from public.ai_usage');
select t.fails('clients cannot write the AI usage counter', $$insert into public.ai_usage (user_id, calls) values (auth.uid(), 0)$$);
select t.fails('clients cannot call ai_consume', $$select public.ai_consume(auth.uid(), 5)$$);
select t.as_anon();
select t.fails('anonymous cannot call ai_consume', $$select public.ai_consume(gen_random_uuid(), 5)$$);
select t.fails('anonymous cannot read reminders', 'select * from public.reminders');
select t.as_service();
select t.ok('server (service role) enforces the daily limit atomically', public.ai_consume('77777777-0000-0000-0000-000000000007', 3) and public.ai_consume('77777777-0000-0000-0000-000000000007', 3) and public.ai_consume('77777777-0000-0000-0000-000000000007', 3) and not public.ai_consume('77777777-0000-0000-0000-000000000007', 3) and not public.ai_consume('77777777-0000-0000-0000-000000000007', 3));
select t.ok('limit is per user (another user still has quota)', public.ai_consume('88888888-0000-0000-0000-000000000008', 3));
select t.su(); select t.ok('the stored counter never exceeds the limit', (select calls from public.ai_usage where user_id = '77777777-0000-0000-0000-000000000007') = 3); select t.as_service();
select t.fails('nonsense limits are refused', $$select public.ai_consume('88888888-0000-0000-0000-000000000008', 0)$$);
select t.su(); delete from auth.users where id in ('77777777-0000-0000-0000-000000000007', '88888888-0000-0000-0000-000000000008');
select t.ok('deleting users removes reminders and AI usage rows', (select count(*) from public.reminders) + (select count(*) from public.ai_usage) = 0);
